// src/components/common/TransactionForm.jsx
import React from 'react';
import './TransactionForm.css';

const TransactionForm = ({ 
  isRepair,                // true if this is a repair claim
  title,
  txData,
  onChange,
  onSubmit,
  onCancel,
  representative,
  prefilledExcessAmount    // for repair, the excess amount is pre‑filled
}) => {
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  // Show additional fee fields only if the user has entered an amount or starts typing
  const showAdditionalFee = txData.additionalFeeAmount && txData.additionalFeeAmount !== '';

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {/* Fault date – only for Replacement */}
        {!isRepair && (
          <div className="field">
            <label>Fault Date *</label>
            <input
              type="date"
              name="faultDate"
              value={txData.faultDate || ''}
              onChange={handleInputChange}
              required
            />
          </div>
        )}

        {/* Excess Amount */}
        <div className="field">
          <label>{isRepair ? 'Excess Amount (auto-filled)' : 'Excess Amount *'}</label>
          <input
            type="text"
            name="excessAmount"
            value={isRepair ? prefilledExcessAmount : txData.excessAmount}
            onChange={isRepair ? undefined : handleInputChange}
            readOnly={isRepair}
            placeholder={isRepair ? 'Auto-filled from system' : 'Enter excess amount'}
            className={isRepair ? 'readonly' : ''}
            required={!isRepair}
          />
          {isRepair && (
            <div className="helper-text">
              <i className="fas fa-info-circle"></i> Amount is pre-filled from claim data
            </div>
          )}
        </div>

        {/* Primary Transaction ID */}
        <div className="field">
          <label>Transaction ID *</label>
          <input
            type="text"
            name="txId"
            value={txData.txId || ''}
            onChange={handleInputChange}
            placeholder="e.g., MP260610.2000.X08195"
            required
          />
        </div>

        {/* Transaction Date – auto‑extracted from primary Tx ID */}
        <div className="field">
          <label>Transaction Date</label>
          <input
            type="text"
            name="date"
            value={txData.date || ''}
            readOnly
            className="readonly"
            placeholder="Auto‑extracted from Transaction ID"
          />
          {txData.date && (
            <div className="helper-text success">
              <i className="fas fa-check-circle"></i> Auto‑extracted from Transaction ID
            </div>
          )}
        </div>

        {/* Additional Fee – only for Replacement, optional */}
        {!isRepair && (
          <>
            <div className="field">
              <label>Additional Fee Amount (Optional)</label>
              <input
                type="text"
                name="additionalFeeAmount"
                value={txData.additionalFeeAmount || ''}
                onChange={handleInputChange}
                placeholder="e.g., 25000"
              />
            </div>
            {showAdditionalFee && (
              <div className="field">
                <label>Additional Fee Transaction ID *</label>
                <input
                  type="text"
                  name="additionalFeeTxId"
                  value={txData.additionalFeeTxId || ''}
                  onChange={handleInputChange}
                  placeholder="e.g., MP260611.3000.X08196"
                />
                <div className="helper-text">
                  <i className="fas fa-info-circle"></i> Required if Additional Fee Amount is entered
                </div>
              </div>
            )}
          </>
        )}

        {/* Agent Name – always visible, read‑only */}
        <div className="field">
          <label>Agent</label>
          <input
            type="text"
            name="agent"
            value={representative || 'Shabani'}
            readOnly
            className="readonly"
          />
        </div>

        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button type="button" className="submit-btn" onClick={onSubmit}>
            <i className="fas fa-check"></i> Submit
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
